#include <stdio.h>

int main() {
    int n;
    int categoria;
    scanf("%d", &n);
    int cuentaA = 0, cuentaB = 0, cuentaC = 0;
    for (int i = 0; i < n; i++) {
        scanf("%d", &categoria);
        switch (categoria) {
            case 1:
                cuentaA++;
                break;
            case 2:
                cuentaB++;
                break;
            case 3:
                cuentaC++;
                break;
        }
    }
    printf("A: %d\nB: %d\nC: %d\n", cuentaA, cuentaB, cuentaC);
    return 0;
}
